-- 0271: las fichas sin direccion publicada reciben la coordenada de su ciudad,
-- marcada SIEMPRE como aproximada.
--
-- Problema medido el 17 de octubre de 2026: de las 1,819 fichas publicadas solo
-- 742 tenian coordenadas, y TODAS eran de Mexico. Espana (372), Portugal (113) y
-- Brasil (82) no tenian ni una. El mapa del directorio se quedaba en su centro
-- por omision (Ciudad de Mexico) mostrando cero marcas, y "Buscar cerca de mi"
-- no podia devolver nada fuera de Mexico.
--
-- 1,044 fichas publicadas tienen ciudad y no tenian coordenada. Sus ciudades son
-- 417 distintas, geocodificadas una por una contra Nominatim (OpenStreetMap) el
-- 17 de octubre de 2026, a una consulta por segundo y con el pais acotado.
--
-- SOBRE LA EXACTITUD, que es lo delicado: esto NO es la direccion del prestador.
-- Es el centro de su ciudad, y el titular de la ficha nunca publico su domicilio.
-- Por eso cada ficha asi queda marcada con `ubicacion_aproximada`: la 0272 lleva
-- esa bandera a las vistas publicas y la interfaz la usa para decirlo con todas
-- sus letras y NO ofrecer "como llegar". Mandar a alguien a conducir hasta un
-- punto que nadie dio seria peor que no tener mapa.
--
-- DOS PASADAS DE VERIFICACION, no una. La primera geocodificacion devolvio 31
-- resultados equivocados que la segunda corrigio acotando a nucleos de poblacion
-- y agregando el estado de la ficha. Ejemplos reales de la primera pasada:
--   · Cadereyta (Queretaro) caia en Cadereyta Jimenez, Nuevo Leon: 700 km lejos.
--   · "Ciudad de Quebec" caia en una calle de Terranova.
--   · Las 8 ciudades de Puerto Rico no devolvian nada: se indexan bajo EE. UU.
-- Y una correccion a mano: "Queretaro" sin estado devolvia el centroide del
-- estado (20.8052,-99.8837); se fijo en la ciudad (20.5923,-100.3917).
--
-- Resultado verificado contra la API publica como visitante anonimo:
--   Espana 361, Portugal 113, Brasil 78, Mexico 1,026 fichas con coordenada,
--   y cero fichas publicadas que tengan ciudad y les falte la coordenada.

alter table public.directorio add column if not exists ubicacion_aproximada boolean not null default false;

comment on column public.directorio.ubicacion_aproximada is
  'La coordenada es el centro de la ciudad, no el domicilio. La interfaz debe decirlo y no ofrecer rutas.';

update public.directorio d set lat=c.lat,lng=c.lng,ubicacion_aproximada=true,actualizada_en=now() from (values ('Cerrillos',-24.9035,-65.4872),('Ciudad Autónoma de Buenos Aires',-34.6096,-58.3888),('Ciudad de Mendoza',-32.8894,-68.8446),('Córdoba',-31.4167,-64.1834),('La Plata',-34.9207,-57.9538),('Quilmes Oeste',-34.7461,-58.2878),('San Isidro',-34.4740,-58.5265),('San Miguel de Tucumán',-26.8304,-65.2038)) as c(ciudad,lat,lng) where d.pais='Argentina' and d.ciudad=c.ciudad and (d.lat is null or d.lng is null);
